    kL = 0.06 * wk + kw * pow(max(0.0, cos(ph + 0.35)), 1.6) + 0.1 * wk * max(0.0, -cos(ph + 0.35));
    kR = 0.06 * wk + kw * pow(max(0.0, -cos(ph + 0.35)), 1.6) + 0.1 * wk * max(0.0, cos(ph + 0.35));
    // Stehen: Gewicht langsam verlagern, ein Knie locker
